mod sparse;mod scheduler;mod bridge;mod bqi;mod check;
#[cfg(test)]mod tests{
use super::*;use scheduler::search::*;use sparse::{Owner,Charge,Polynomial};use std::time::{Instant,Duration};
#[derive(Default)]struct Ledger{work:u64,bytes:u64,checks:u64,stop:Option<u64>}
impl Owner for Ledger{fn reserve(&mut self,q:Charge)->Result<(),()>{self.work+=q.work;self.bytes+=q.bytes;Ok(())}fn check(&mut self)->Result<(),()>{self.checks+=1;if self.stop==Some(self.checks){Err(())}else{Ok(())}}}
fn sl()->SearchLimits{SearchLimits{nodes:32,native:scheduler::Limits{batch_rows:128,batch_ops:1024,batches:32,variables:256,generators:64,basis:64,tasks:1024,terms:256,proof:1024,degree:256,work:20_000_000,bytes:200_000_000}}}
fn cl()->check::Limits{check::Limits{nodes:32,work:2_000_000_000,bytes:400_000_000,certificate:bridge::Limits{variables:256,generators:64,terms:256,degree:256,proof:1024,wire:65536,work:1_000_000_000,bytes:200_000_000},checker:bqi::Limits::software()}}
fn deadline()->Instant{Instant::now()+Duration::from_secs(10)}
fn system()->Vec<Polynomial>{vec![vec![vec![],vec![0]],vec![vec![],vec![1],vec![2]]]}
fn run(g:&[Polynomial])->SearchAttempt{solve(3,g,sl(),deadline(),&mut Ledger::default())}
#[test]fn real_branch_witness_and_refutation_checked(){let g=system();let a=run(&g);let mut owner=Ledger::default();let audit=check::verify(3,&g,&a,cl(),deadline(),&mut owner);assert_eq!(audit.result,Ok(()));assert_eq!(audit.checked_nodes,a.nodes.len());assert!(!audit.certificates.is_empty());assert_eq!(audit.charge.work,owner.work);assert_eq!(audit.charge.bytes,owner.bytes);assert!(!audit.source_authenticated);}
#[test]fn root_unsat_checked(){let g=vec![vec![vec![0]],vec![vec![],vec![0]]];let a=run(&g);assert_eq!(a.verdict,Verdict::UnsatDerived);assert_eq!(check::verify(3,&g,&a,cl(),deadline(),&mut Ledger::default()).result,Ok(()));}
#[test]fn branch_coverage_origin_source_model_queue_and_proof_mutations_reject(){let g=system();for mode in 0..9{let mut a=run(&g);match mode{0=>a.nodes[0].children[1]=None,1=>{let child=a.nodes[0].children[0].unwrap();a.nodes[child].origins[0]=Origin::Original(1)},2=>a.nodes[0].equations[0]=vec![],3=>{let i=a.witness_node.unwrap();a.nodes[i].candidate[0]=false},4=>a.queue.push(0),5=>{let i=a.nodes[0].children[0].unwrap();let row=a.nodes[i].refutation_row.unwrap();a.nodes[i].native.as_mut().unwrap().basis[row].proof.clear()},6=>{let i=a.nodes[0].children[1].unwrap();a.nodes[i].decisions.last_mut().unwrap().0=1},7=>a.nodes[0].children[1]=a.nodes[0].children[0],_=>{a.verdict=Verdict::UnsatDerived;a.witness_node=None}};assert!(check::verify(3,&g,&a,cl(),deadline(),&mut Ledger::default()).result.is_err(),"mode {mode}");}}
#[test]fn unknown_and_parent_stops_never_verify(){let g=system();let mut l=sl();l.nodes=1;let a=solve(3,&g,l,deadline(),&mut Ledger::default());assert_eq!(a.verdict,Verdict::Unknown);assert!(check::verify(3,&g,&a,cl(),deadline(),&mut Ledger::default()).result.is_err());let a=run(&g);let mut base=Ledger::default();assert!(check::verify(3,&g,&a,cl(),deadline(),&mut base).result.is_ok());for stop in 1..=base.checks{let mut owner=Ledger{stop:Some(stop),..Default::default()};let v=check::verify(3,&g,&a,cl(),deadline(),&mut owner);assert_eq!(v.result,Err(check::Failure::Owner));assert_eq!(v.charge.work,owner.work);assert_eq!(v.charge.bytes,owner.bytes);}assert_eq!(check::verify(3,&g,&a,cl(),Instant::now(),&mut Ledger::default()).result,Err(check::Failure::Deadline));let mut l=cl();l.work=100;assert_eq!(check::verify(3,&g,&a,l,deadline(),&mut Ledger::default()).result,Err(check::Failure::Cap));}
}
